const WINDOWS_1252 =
  "\u20ac\u0081\u201a\u0192\u201e\u2026\u2020\u2021\u02c6\u2030\u0160\u2039\u0152\u008d\u017d\u008f\u0090\u2018\u2019\u201c\u201d\u2022\u2013\u2014\u02dc\u2122\u0161\u203a\u0153\u009d\u017e\u0178";

export const ENTITIES: ReadonlyMap<string, string> = new Map(
  DATA.split("\u0000")
    .filter((entry) => entry !== "")
    .map((entry): [string, string] => {
      const at = entry.indexOf("\u0001");
      return [entry.slice(0, at), entry.slice(at + 1)];
    }),
);

export const windows1252 = (code: number): string | undefined =>
  code >= 0x80 && code <= 0x9f ? WINDOWS_1252.charAt(code - 0x80) : undefined;
